# =================================================================
# MAPA BASE DE GEOMETRÍAS
# ARCHIVO GENERADO AUTOMÁTICAMENTE A PARTIR DE LA DEFINICIÓN: layers.03_rezago_educativo.02_rezago_localidad_rural 
# DESCRIPCIÓN: Localidades rurales con rezago educativo Censo 2020 
# =================================================================

LAYER
  NAME "c_analfabetas"
  STATUS ON
  TYPE POINT
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, analfabetas FROM rezago_educativo_censo_2020.rez_loc_rur WHERE the_geom && !BOX!) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Número de personas en condición de analfabetizmo por localidad rural"
    "wms_enable_request" "*"
  END
  CLASS
    SYMBOL "circulor"
    SIZE 6
    OUTLINECOLOR 42 212 48
    NAME "Localidad - Rezago Bajo"
    COLOR 42 212 48
    EXPRESSION ([Cluster_FeatureCount] = 1 AND [analfabetas] < 10)
  END
  CLASS
    SYMBOL "circulor"
    SIZE 7
    OUTLINECOLOR 253 141 60
    NAME "Localidad - Rezago Medio"
    COLOR 253 141 60
    EXPRESSION ([Cluster_FeatureCount] = 1 AND [analfabetas] >= 10 AND [analfabetas] < 50)
  END
  CLASS
    SYMBOL "circulor"
    SIZE 8
    OUTLINECOLOR 227 26 28
    NAME "Localidad - Rezago Alto"
    COLOR 227 26 28
    EXPRESSION ([Cluster_FeatureCount] = 1 AND [analfabetas] >= 50)
  END
  CLASS
    SYMBOL "circulor"
    SIZE 14
    OUTLINECOLOR 220 220 220
    NAME "Grupo Pequeño (2-49)"
    COLOR 180 180 180
    EXPRESSION ([Cluster_FeatureCount] > 1 AND [Cluster_FeatureCount] < 50)
    LABEL
      TEXT "[Cluster_FeatureCount]"
      FONT "arial"
      TYPE truetype
      SIZE 8
      ALIGN center
      POSITION cc
      FORCE true
      COLOR 0 0 0
    END
  END
  CLASS
    SYMBOL "circulor"
    SIZE 22
    OUTLINECOLOR 180 180 180
    NAME "Grupo Medio (50-499)"
    COLOR 120 120 120
    EXPRESSION ([Cluster_FeatureCount] >= 50 AND [Cluster_FeatureCount] < 500)
    LABEL
      TEXT "[Cluster_FeatureCount]"
      FONT "arial"
      TYPE truetype
      SIZE 9
      ALIGN center
      POSITION cc
      FORCE true
      COLOR 255 255 255
    END
  END
  CLASS
    SYMBOL "circulor"
    SIZE 32
    OUTLINECOLOR 120 120 120
    NAME "Grupo Grande (>=500)"
    COLOR 70 70 70
    EXPRESSION ([Cluster_FeatureCount] >= 500)
    LABEL
      TEXT "[Cluster_FeatureCount]"
      FONT "arial"
      TYPE truetype
      SIZE 11
      ALIGN center
      POSITION cc
      FORCE true
      COLOR 255 255 255
    END
  END
  PROCESSING "CLOSE_CONNECTION=DEFER"
  CLUSTER
    MAXDISTANCE 25
    REGION "rectangle"
    BUFFER 0
  END
  CLASSITEM "Cluster_FeatureCount"
END

